example.programlisting:
using System;
using Rexx.Net;

Func<string, RexxCommandContext, object?> calc = (command, caller) =>
{
    var words = command.Split(' ');
    int n = int.Parse(words[^1]);                      // not a number: a .NET error
    if (words[0] == "square") return n * n;
    if (words[0] == "table")
    {
        for (int i = 1; i <= 3; i++) caller.Output.Send("LINEOUT", $"{n} x {i} = {n * i}");
        return 0;
    }
    return caller.RaiseError(-1);
};
using var rexx = RexxInterpreter.Create(new RexxOptions { StreamPrefixes = false });
rexx.Run("""
    use arg calc
    .CommandHandler~register("CALC", .NetCommandHandler~new(calc))
    address calc "square 7"; say "rc:" rc
    out = .array~new
    address calc "table 7" with output using (out)
    say out~makeString("l", " / ")
    signal on syntax
    address calc "square x"
    syntax:
      c = condition("O")
      say c~code .net~typeOf(c~additional[2])
    .CommandHandler~deregister("calc")
    signal on failure
    trace off                                         -- (TRACE NORMAL shows failures)
    address calc "square 7"
    failure: say "FAILURE, rc" rc
    ::requires "net.cls"
    """, calc);
